<?php declare(strict_types=1);
putenv('KH_NATIVE_MANAGER=1');putenv('VEREIN_AUTH=native');
require dirname(__DIR__).'/src/bootstrap.php';
require dirname(__DIR__).'/native/bootstrap.php';
require dirname(__DIR__).'/src/Web/View.php';
use Kulturhus\Native\Integration\{ManagerBridge,ContactCommunicationStatus};
use Kulturhus\Native\Communication\{Subscribers,PressContacts};
use Kulturhus\Native\Shared\Db;
use Kulturhus\Verein\{Database,Registry,WebsiteContactStatus};

$db=\Kulturhus\Native\TestSupport::db();Database::migrate($db);
\Kulturhus\Native\Integration\Schema::install($db);
\Kulturhus\Native\Communication\Schema::install($db);
$db->exec("INSERT INTO clubs VALUES('status-a','Synthetic own club'),('status-b','Synthetic other club');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('status-admin','status-a','members',1),('status-other','status-b','members',1),('status-member','status-a','member',0),('status-editor','status-a','editor',0)");
$registry=new Registry($db,'status-admin');$otherRegistry=new Registry($db,'status-other');
$person=$registry->saveContact(null,0,'person','Synthetic status person',' Status.Person@example.invalid ','');
$empty=$registry->saveContact(null,0,'person','No newsletter address','','');
$foreignPerson=$otherRegistry->saveContact(null,0,'person','Foreign same address','status.person@example.invalid','');
Db::run($db,'UPDATE actors SET contact_id=? WHERE id=?',[$person,'status-member']);
$own=(new ManagerBridge($db,'status-admin','native',static fn()=>null))->access();
$foreign=(new ManagerBridge($db,'status-other','native',static fn()=>null))->access();
$subscribers=new Subscribers($db,$own);$otherSubscribers=new Subscribers($db,$foreign);
$press=new PressContacts($db,$own);$otherPress=new PressContacts($db,$foreign);
$checks=0;$check=static function(bool $ok,string $label)use(&$checks):void{if(!$ok)throw new RuntimeException($label);++$checks;echo 'PASS '.$label."\n";};
$deny=static function(callable $fn,string $label)use($check):void{try{$fn();}catch(DomainException){$check(true,$label);return;}throw new RuntimeException($label);};
$read=static fn()=> (new WebsiteContactStatus($db,'status-admin'))->forContact($person);
$check((new WebsiteContactStatus($db,'status-admin'))->forContact($empty)['state']==='no-address','authorized contact without an address has an explicit empty state');
$check($read()['matches']===[]&&$read()['press']===[],'new profile never invents a subscription or press entry');
$token='';$subscriber=$subscribers->requestConsent('status.person@example.invalid','Private subscriber name',['events'],'Synthetic private consent evidence',static function(string $t)use(&$token):void{$token=$t;});
$otherSubscribers->recordWrittenConsent('status.person@example.invalid','Foreign private name',['events'],'Synthetic foreign consent evidence');
$otherPress->save(['email'=>'status.person@example.invalid','name'=>'Foreign press name','outlet'=>'Foreign secret outlet','active'=>true]);
$state=$read();$check($state['matches'][0]['status']==='pending'&&$state['press']===[],'pending own consent and foreign matching address stay separate');
$check($subscribers->confirm($token),'actual native confirmation succeeds');
$check($read()['matches'][0]['status']==='confirmed'&&$read()['matches'][0]['confirmed_at']!==null,'profile reads current confirmation without a website transport');
$pressRow=$press->save(['email'=>'status.person@example.invalid','name'=>'Private press name','outlet'=>'Own <Outlet>','active'=>true]);
$state=$read();$check($state['press']===[['outlet'=>'Own <Outlet>','active'=>1]],'only narrow current own press status is returned');
$check(array_keys($state['matches'][0])===['status','confirmed_at','unsubscribed_at'],'tokens, names, email and consent evidence are excluded');
$wire=json_encode($state,JSON_THROW_ON_ERROR);$check(!str_contains($wire,$token)&&!str_contains($wire,'Foreign')&&!str_contains($wire,'Private')&&!str_contains($wire,'consent evidence'),'private tokens and unrelated recipient details cannot leak');
$member=new ContactCommunicationStatus($db,'status-member');$check($member->forContact($person)['matches'][0]['status']==='confirmed','personal member can read only their current profile status');
$deny(fn()=>$member->forContact($empty),'member cannot inspect another same-club profile');
$deny(fn()=>(new ContactCommunicationStatus($db,'status-admin'))->forContact($foreignPerson),'foreign profile is denied before lookup');
$deny(fn()=>(new ContactCommunicationStatus($db,'status-editor'))->forContact($person),'website editor has no member profile access');
$duplicate=$registry->saveContact(null,0,'person','Shared-address contact','status.person@example.invalid','');
$state=$read();$check($state['state']==='ambiguous'&&$state['shared_address_profiles']===2,'shared email is identified without attributing consent to one person');
Db::run($db,"UPDATE contacts SET archived_at=UTC_TIMESTAMP() WHERE id=?",[$duplicate]);
$check($read()['state']==='available'&&$read()['shared_address_profiles']===1,'archived duplicate is excluded from the current profile count');
$press->save(array_replace($pressRow,['active'=>false]),1);$check($read()['press'][0]['active']===0,'press deactivation is reflected on the next read');
$subscribers->issueUnsubscribe($subscriber['id'],static function(string $t)use(&$token):void{$token=$t;});$check($subscribers->unsubscribe($token),'actual native consent withdrawal succeeds');
$check($read()['matches'][0]['status']==='unsubscribed','withdrawal is immediately reflected without cache');
Db::run($db,'UPDATE actors SET active=0 WHERE id=?',['status-member']);$deny(fn()=>$member->forContact($person),'current account suspension prevents a previously authorized read');Db::run($db,'UPDATE actors SET active=1 WHERE id=?',['status-member']);
$snapshot=static function()use($db):array{$out=[];foreach(['contacts','actors','khn_newsletter_subscribers','khn_newsletter_tokens','khn_newsletter_consent_events','khn_press_contacts','native_manager_identities','audit_events'] as $table)$out[$table]=hash('sha256',json_encode($db->query('SELECT * FROM '.$table)->fetchAll(),JSON_THROW_ON_ERROR));return $out;};
$before=$snapshot();$read();$member->forContact($person);$check($before===$snapshot(),'status reads preserve all profile, consent, token, identity and audit originals');
$profile=$registry->contact($person);$_SESSION=['actor'=>'status-admin'];ob_start();require dirname(__DIR__).'/views/Website/website-contact-status.php';$html=ob_get_clean();
$check(str_contains($html,'Abgemeldet')&&str_contains($html,'Own &lt;Outlet&gt; (inaktiv)'),'actual member widget renders current consent, inactive press and escaped outlet');
$check(!str_contains($html,'nicht erreichbar')&&!str_contains($html,'Bestätigungslink'),'native status never claims an unavailable legacy transport or an unproven consent source');
Db::run($db,'UPDATE contacts SET email=?,version=version+1 WHERE id=?',['new-address@example.invalid',$person]);$check($read()['matches']===[]&&$read()['press']===[],'changed profile address cannot retain status from an old address');
putenv('KH_NATIVE_MANAGER=0');$check((new WebsiteContactStatus($db,'status-admin'))->forContact($person)['state']==='unavailable','unconfigured synthetic compatibility view cannot read native recipients');
echo json_encode(['suite'=>'native-contact-status','checks'=>$checks,'transport'=>'none'],JSON_THROW_ON_ERROR)."\n";
